const aiOutput = JSON.parse($input.first().json.output);

// 數據在 chunks 裡
const dataArray = Array.isArray(aiOutput) 
  ? aiOutput 
  : Array.isArray(aiOutput.data) 
    ? aiOutput.data 
    : Array.isArray(aiOutput.output) 
      ? aiOutput.output 
      : Array.isArray(aiOutput.results)
        ? aiOutput.results
        : Array.isArray(aiOutput.chunks)
          ? aiOutput.chunks
          : [];

if (dataArray.length === 0) {
  return { error: 'No data found', debug: aiOutput };
}

// ✅ 從上游 Get Episode Data from Sheets 取得 episode_id

const episodeId = $('Get Episode Data from Sheets').first().json.episode_id || 1;

const results = dataArray.map((item) => {
  const {
    order,
    section,
    script,
    target_words,
    style_prompt
  } = item;

  // ✅ 簡單 if 判斷：只有兩種 voice 組合
  let speaker1_name, speaker2_name, voice1_name, voice2_name;

  if (section === 'full_conversation_part_1' || section === 'full_conversation_part_2') {
    // full_conversation → Tom & Anna (Fenrir & Vindemiatrix)
    speaker1_name = 'Tom';
    speaker2_name = 'Anna';
    voice1_name = 'Fenrir';
    voice2_name = 'Vindemiatrix';
  } else {
    // 其他所有 section → Riley & Jordan (Kore & Achird)
    speaker1_name = 'Riley';
    speaker2_name = 'Jordan';
    voice1_name = 'Kore';
    voice2_name = 'Achird';
  }

  const speakers = [speaker1_name, speaker2_name].filter(Boolean);
  const isSingleSpeaker = speakers.length === 1;

  // ✅ 生成完整的 filename path
  const filename = `/mnt/gdrive/bolt_english/tts_output/ep_${episodeId}/${order}_${section}.wav`;

  return {
    text:script,
    style_prompt,
    speaker1_name,
    speaker2_name,
    voice1_name,
    voice2_name,
    filename,
  };
});

return results;

